changeSet.sql:
DECLARE
    v_start NUMBER;
BEGIN
    SELECT NVL(MAX(id), 0) + 1 INTO v_start FROM items;
    EXECUTE IMMEDIATE 'CREATE SEQUENCE items_seq START WITH ' || v_start || ' INCREMENT BY 50';
    SELECT NVL(MAX(id), 0) + 1 INTO v_start FROM storage;
    EXECUTE IMMEDIATE 'CREATE SEQUENCE storage_seq START WITH ' || v_start || ' INCREMENT BY 50';
    SELECT NVL(MAX(id), 0) + 1 INTO v_start FROM item_instance;
    EXECUTE IMMEDIATE 'CREATE SEQUENCE item_instance_seq START WITH ' || v_start || ' INCREMENT BY 50';
END;
